// Gate + shape. This is deliberately ALL this workflow does itself — the
// change/render heavy lifting is delegated to the engine sub-workflow
// (workflow.yakyak-engine.json) two nodes down. The webhook token check that
// used to live here is now the webhook node's Header Auth credential.
const body = $('Patch request').first().json.body || {};
if (!body.movieId) throw new Error('body.movieId is required (the ?movieId= param on the IG grid)');
// dialogue is OPTIONAL: omit it for render-only mode — no edit, the engine
// just resolves the movie, re-renders, and the video is delivered as usual.
let dialogue = String(body.dialogue || '').trim();
// YakYak convention: dialogue must not end in a period ("!" / "?" are fine)
dialogue = dialogue.replace(/\.+$/, '');
const renderOnly = !dialogue;
const sceneNumber = Number(body.sceneNumber || 1);
if (!renderOnly && (!Number.isInteger(sceneNumber) || sceneNumber < 1)) throw new Error('body.sceneNumber must be a positive integer');
// Routing: one shape for every channel. Each bot credential can post anywhere,
// so the destination travels with the request; a present key = deliver there.
const dt = body.deliverTo || {};
const deliverTo = {
  telegram: String(dt.telegram || '').trim(),
  discord: String(dt.discord || '').trim(),
  slack: String(dt.slack || '').trim(),
};
if (!deliverTo.telegram && !deliverTo.discord && !deliverTo.slack) {
  throw new Error('deliverTo must name at least one channel, e.g. {"deliverTo":{"telegram":"175991…","discord":"138512…","slack":"C0BF…"}}');
}
return [{ json: { movieId: body.movieId, dialogue, sceneNumber, renderOnly, deliverTo } }];

// The engine's sub-workflow trigger is passthrough: this item has the same
// shape as the engine webhook's body. movieId alone is enough — the engine
// derives the campaign from the movie, so no userId needed on this path.
// Render-only mode sends an empty change plan: the engine resolves the movie,
// regenerates nothing, and re-renders (concat + soundtrack only).
const v = $json;
const scenes = v.renderOnly ? [] : [{ sceneNumber: v.sceneNumber, action: 'dialogue', dialogue: v.dialogue }];
return [{ json: { target: { mode: 'patch', movieId: v.movieId }, changes: { scenes }, chatWebhookUrl: '' } }];

// THE CHANNEL SEAM. Everything upstream is delivery-agnostic; everything
// downstream is one parallel branch per channel — each gated by an IF on its
// deliverTo key, fanned out from this node and fanned back in at 'Merge
// deliveries'. Each branch gets the same payload:
//   url       — the rendered movie (direct mp4 link)
//   caption   — human text that ENDS WITH the url, so plain-text channels
//               (Teams/Mattermost/email/SMS…) can send it as-is and
//               link-unfurling channels get an inline player for free
//   deliverTo — the per-channel destination ids from the request body
//   result    — the machine-readable summary echoed to the webhook caller
// To add a channel: copy the Discord branch (IF on your deliverTo key → your
// node → a new Merge input), set onError=continue so it can't kill the others,
// and add one guarded line in 'Finalize delivery'.
const r = $json;
if (!r.url) throw new Error('engine returned no movie URL: ' + JSON.stringify(r).slice(0, 200));
const v = $('Validate').first().json;
const changed = Number(r.changed || 0);
const caption = v.renderOnly
  ? `🎬 Movie re-rendered (no edit):
${r.url}`
  : `🎬 Scene ${v.sceneNumber} dialogue ${changed ? 'updated' : 'unchanged (no-op — same line as before)'}:
“${v.dialogue}”
${r.url}`;
const result = Object.assign({ url: r.url, movieId: v.movieId, changed },
  v.renderOnly ? { renderOnly: true } : { sceneNumber: v.sceneNumber, dialogue: v.dialogue });
return [{ json: { url: r.url, caption, deliverTo: v.deliverTo, result } }];

// Reached via Send video's error output; Send link itself is also non-fatal
// (onError=continue) so a total Telegram failure can't block the other
// channels or the webhook response — it just reports 'failed'.
const c = $('Compose message').first().json;
return [{ json: { ...c.result, delivered: $json.error ? 'failed' : 'link' } }];

// Channel-agnostic fan-in: one status per deliverTo key. Every node reference
// is guarded, so deleting a channel branch (or adding one — extend the pattern
// below) doesn't break this node.
const c = $('Compose message').first().json;
const to = $('Validate').first().json.deliverTo;
const deliveries = {};
if (to.telegram) {
  deliveries.telegram = 'failed';
  try { deliveries.telegram = $('Mark delivered (link)').first().json.delivered; }
  catch (e) { try { deliveries.telegram = $('Mark delivered (video)').first().json.delivered; } catch (e2) {} }
} else { deliveries.telegram = 'skipped'; }
if (to.discord) { try { deliveries.discord = $('Send to Discord').first().json.error ? 'failed' : 'sent'; } catch (e) { deliveries.discord = 'failed'; } } else { deliveries.discord = 'skipped'; }
if (to.slack) { try { deliveries.slack = $('Send to Slack').first().json.error ? 'failed' : 'sent'; } catch (e) { deliveries.slack = 'failed'; } } else { deliveries.slack = 'skipped'; }
return [{ json: { ...c.result, deliveries } }];
